#!/usr/bin/env bash
# Description: Add the Provider Execution foundation.
set -Eeuo pipefail
PROJECT_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
EXPECTED_BASELINE="22b9b68"
PATCH_FILE="$(mktemp)"
trap 'rm -f "${PATCH_FILE}"' EXIT
if [[ "$(git -C "${PROJECT_ROOT}" rev-parse --short=7 HEAD)" != "${EXPECTED_BASELINE}" ]]; then printf '%s\n' "ERROR: This generator requires baseline ${EXPECTED_BASELINE}." >&2; exit 1; fi
base64 -d <<'PROVIDER_EXECUTION_PATCH' | gzip -d > "${PATCH_FILE}"

PROVIDER_EXECUTION_PATCH
if git -C "${PROJECT_ROOT}" apply --check "${PATCH_FILE}" >/dev/null 2>&1; then git -C "${PROJECT_ROOT}" apply "${PATCH_FILE}"; printf '%s\n' 'Provider Execution foundation generated.'; exit 0; elif git -C "${PROJECT_ROOT}" apply --reverse --check "${PATCH_FILE}" >/dev/null 2>&1; then printf '%s\n' 'Provider Execution foundation is already present.'; exit 0; else printf '%s\n' 'ERROR: Provider Execution generator found conflicting managed files.' >&2; exit 1; fi
